/**
 * Drizzle table definitions (docs/ARCHITECTURE.md §5). drizzle-kit generates SQL migrations from this file
 * into /db/migrations; review the generated SQL before committing it.
 *
 * Conventions: UUID primary keys generated by the server (ciphertexts are bound to them, §6.2); timestamps are
 * timestamptz; encrypted fields are a `*_ct` (ciphertext + tag) and `*_nonce` pair of BYTEA columns.
 */
import { sql } from 'drizzle-orm';
import {
  bigint,
  boolean,
  check,
  date,
  customType,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

const bytea = customType<{ data: Buffer; driverData: Buffer }>({ dataType: () => 'bytea' });
const timestamptz = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });

export const roleEnum = pgEnum('role', ['NORMAL_USER', 'COURSE_LEADER', 'SYS_ADMIN']);
export const themeEnum = pgEnum('theme', ['light', 'dark', 'system']);
export const sessionKindEnum = pgEnum('session_kind', ['browser', 'device']);
/**
 * Second-factor state of a session:
 *  - not_required: the account has no TOTP; the session is complete.
 *  - pending: password accepted, waiting for the authenticator code.
 *  - enrolment_required: a SYS_ADMIN without TOTP; may only set it up.
 *  - verified: TOTP checked in this session.
 */
export const mfaStateEnum = pgEnum('mfa_state', [
  'not_required',
  'pending',
  'enrolment_required',
  'verified',
]);

export const users = pgTable(
  'users',
  {
    id: uuid('id').primaryKey(),
    /** As the user typed it; uniqueness and login are case-insensitive (see index). Immutable. */
    username: text('username').notNull(),
    email: text('email'),
    role: roleEnum('role').notNull(),
    /** argon2id PHC string; includes its own parameters so they can be raised later. */
    passwordHash: text('password_hash').notNull(),
    /** Forgot-password lock-out (spec §4.3): login is refused until a SYS_ADMIN sets a new password. */
    resetPending: boolean('reset_pending').notNull().default(false),
    /** TOTP secret, encrypted with the user's profile DEK. */
    totpSecretCt: bytea('totp_secret_ct'),
    totpSecretNonce: bytea('totp_secret_nonce'),
    totpEnabledAt: timestamptz('totp_enabled_at'),
    /** Last accepted TOTP time step, so a code can't be used twice. */
    totpLastStep: integer('totp_last_step'),
    fontSize: smallint('font_size').notNull().default(18),
    theme: themeEnum('theme').notNull().default('system'),
    /** {familyName, givenName, address, photo} as encrypted JSON. */
    profileCt: bytea('profile_ct').notNull(),
    profileNonce: bytea('profile_nonce').notNull(),
    /** The user's profile DEK, wrapped by PROFILE_KEYRING. */
    profileDekWrapped: bytea('profile_dek_wrapped').notNull(),
    lastLoginAt: timestamptz('last_login_at'),
    createdAt: timestamptz('created_at').notNull().defaultNow(),
    updatedAt: timestamptz('updated_at').notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex('users_username_lower_key').on(sql`lower(${t.username})`),
    check('users_font_size_check', sql`${t.fontSize} IN (16, 18, 20, 22)`),
    check(
      'users_totp_pair_check',
      sql`(${t.totpSecretCt} IS NULL) = (${t.totpSecretNonce} IS NULL)`,
    ),
    uniqueIndex('users_email_lower_key')
      .on(sql`lower(${t.email})`)
      .where(sql`${t.email} IS NOT NULL`),
    index('users_role_idx').on(t.role),
  ],
);

export const sessions = pgTable(
  'sessions',
  {
    /** SHA-256 of the random token in the cookie; the token itself is never stored. */
    idHash: bytea('id_hash').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    kind: sessionKindEnum('kind').notNull(),
    /** e.g. "iPhone · Safari", from the user agent at login; shown in Account → Devices. */
    deviceLabel: text('device_label').notNull(),
    csrfToken: text('csrf_token').notNull(),
    mfa: mfaStateEnum('mfa').notNull(),
    createdAt: timestamptz('created_at').notNull().defaultNow(),
    lastSeenAt: timestamptz('last_seen_at').notNull().defaultNow(),
    expiresAt: timestamptz('expires_at').notNull(),
    revokedAt: timestamptz('revoked_at'),
  },
  (t) => [index('sessions_user_idx').on(t.userId), index('sessions_expires_idx').on(t.expiresAt)],
);

export const captchas = pgTable(
  'captchas',
  {
    id: uuid('id').primaryKey(),
    /** HMAC of the answer under SESSION_SECRET; the answer itself is never stored or sent. */
    answerHash: bytea('answer_hash').notNull(),
    expiresAt: timestamptz('expires_at').notNull(),
  },
  (t) => [index('captchas_expires_idx').on(t.expiresAt)],
);

// ---------------------------------------------------------------------------------------------------------
// Activity, Attention list and alerts (docs/ARCHITECTURE.md §8.9, D26, D27). Metadata only: never content,
// titles or profile fields.

export const activityKindEnum = pgEnum('activity_kind', [
  'entry_created',
  'entry_submitted',
  'entry_updated',
  'count_entry',
  'limit_reached',
  'elevated_activity',
  'login',
  'login_failed',
  'new_device',
  'password_changed',
]);

export const activityEvents = pgTable(
  'activity_events',
  {
    id: uuid('id').primaryKey(),
    /** Null once the user is deleted; `username` keeps the event readable. */
    userId: uuid('user_id').references(() => users.id, { onDelete: 'set null' }),
    username: text('username').notNull(),
    kind: activityKindEnum('kind').notNull(),
    /** Small structured facts, e.g. {"device": "iPhone · Safari"} or {"limit": "submit"}. Never content. */
    detail: jsonb('detail').$type<Record<string, string | number | boolean>>(),
    createdAt: timestamptz('created_at').notNull().defaultNow(),
  },
  (t) => [
    index('activity_user_time_idx').on(t.userId, t.createdAt),
    index('activity_kind_time_idx').on(t.kind, t.createdAt),
  ],
);

export const alertRuleEnum = pgEnum('alert_rule', [
  'limit_reached',
  'elevated_activity',
  'login_failures',
  'new_devices',
]);

export const alerts = pgTable(
  'alerts',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id').references(() => users.id, { onDelete: 'set null' }),
    username: text('username').notNull(),
    rule: alertRuleEnum('rule').notNull(),
    createdAt: timestamptz('created_at').notNull().defaultNow(),
    handledBy: uuid('handled_by').references(() => users.id, { onDelete: 'set null' }),
    handledAt: timestamptz('handled_at'),
    emailedAt: timestamptz('emailed_at'),
    emailAttempts: integer('email_attempts').notNull().default(0),
    lastError: text('last_error'),
  },
  (t) => [
    // While an alert for a user and rule is unhandled, further triggers don't add more rows.
    uniqueIndex('alerts_open_user_rule_key')
      .on(t.userId, t.rule)
      .where(sql`${t.handledAt} IS NULL`),
    index('alerts_created_idx').on(t.createdAt),
  ],
);

export const jobStatusEnum = pgEnum('job_status', ['running', 'ok', 'failed']);

/** One row per run of a scheduled job, so a missed or failed run is visible (engineering standards §12.7). */
export const jobRuns = pgTable(
  'job_runs',
  {
    id: uuid('id').primaryKey(),
    job: text('job').notNull(),
    startedAt: timestamptz('started_at').notNull(),
    finishedAt: timestamptz('finished_at'),
    status: jobStatusEnum('status').notNull(),
    /** Counts only, e.g. {"deleted": 12}. */
    summary: jsonb('summary').$type<Record<string, number>>(),
    error: text('error'),
  },
  (t) => [index('job_runs_job_time_idx').on(t.job, t.startedAt)],
);

// ---------------------------------------------------------------------------------------------------------
// Diary entries (spec §5, docs/ARCHITECTURE.md §5). Content, drafts, versions and comments are encrypted with
// the entry's own DEK, which is wrapped by DIARY_KEYRING. Only server/src/services/diary/ handles them.

export const accessEnum = pgEnum('access', ['private', 'wait_for_open', 'open']);

export const documents = pgTable(
  'documents',
  {
    id: uuid('id').primaryKey(),
    ownerId: uuid('owner_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    /** The submitted title (plaintext, spec §3); before the first submit, the working title. */
    title: text('title').notNull(),
    /** A pending title change that leaders don't see yet; null when nothing is pending. */
    draftTitle: text('draft_title'),
    /** The Beijing date of creation, set by the server (spec §5.1, D22). */
    diaryDate: date('diary_date', { mode: 'string' }).notNull(),
    /** What leaders see: the last submitted body. */
    contentCt: bytea('content_ct'),
    contentNonce: bytea('content_nonce'),
    /** The owner's pending body; null when nothing is pending. */
    draftCt: bytea('draft_ct'),
    draftNonce: bytea('draft_nonce'),
    draftSavedAt: timestamptz('draft_saved_at'),
    firstSubmittedAt: timestamptz('first_submitted_at'),
    lastSubmittedAt: timestamptz('last_submitted_at'),
    access: accessEnum('access').notNull().default('private'),
    /** Who last changed sharing, and when (for a waiting entry: the owner's request). */
    accessDecidedBy: uuid('access_decided_by').references(() => users.id, { onDelete: 'set null' }),
    accessDecidedAt: timestamptz('access_decided_at'),
    dekWrapped: bytea('dek_wrapped').notNull(),
    /** Copy of the wrapped key's version, so key rotation can find old ones with an index. */
    keyVersion: integer('key_version').notNull(),
    createdAt: timestamptz('created_at').notNull(),
    updatedAt: timestamptz('updated_at').notNull(),
  },
  (t) => [
    index('documents_owner_date_idx').on(t.ownerId, t.diaryDate),
    index('documents_submitted_date_idx')
      .on(t.diaryDate)
      .where(sql`${t.firstSubmittedAt} IS NOT NULL`),
    index('documents_access_idx').on(t.access),
    index('documents_key_version_idx').on(t.keyVersion),
    check('documents_content_pair', sql`(${t.contentCt} IS NULL) = (${t.contentNonce} IS NULL)`),
    check('documents_draft_pair', sql`(${t.draftCt} IS NULL) = (${t.draftNonce} IS NULL)`),
    check(
      'documents_submitted_has_content',
      sql`(${t.firstSubmittedAt} IS NULL) = (${t.contentCt} IS NULL)`,
    ),
    check(
      'documents_only_submitted_shared',
      sql`${t.access} = 'private' OR ${t.firstSubmittedAt} IS NOT NULL`,
    ),
  ],
);

export const documentVersions = pgTable(
  'document_versions',
  {
    id: uuid('id').primaryKey(),
    documentId: uuid('document_id')
      .notNull()
      .references(() => documents.id, { onDelete: 'cascade' }),
    versionNo: integer('version_no').notNull(),
    contentCt: bytea('content_ct').notNull(),
    contentNonce: bytea('content_nonce').notNull(),
    createdAt: timestamptz('created_at').notNull(),
  },
  (t) => [uniqueIndex('document_versions_doc_no_key').on(t.documentId, t.versionNo)],
);

export const commentStateEnum = pgEnum('comment_state', ['draft', 'submitted']);

/** One per leader per entry (spec §3). A comment is either a draft (only its leader sees it) or submitted. */
export const comments = pgTable(
  'comments',
  {
    id: uuid('id').primaryKey(),
    documentId: uuid('document_id')
      .notNull()
      .references(() => documents.id, { onDelete: 'cascade' }),
    /** Null once the leader's account is deleted: the comment then shows as from a former leader. */
    authorId: uuid('author_id').references(() => users.id, { onDelete: 'set null' }),
    bodyCt: bytea('body_ct').notNull(),
    bodyNonce: bytea('body_nonce').notNull(),
    state: commentStateEnum('state').notNull(),
    submittedAt: timestamptz('submitted_at'),
    seenByOwnerAt: timestamptz('seen_by_owner_at'),
    createdAt: timestamptz('created_at').notNull(),
    updatedAt: timestamptz('updated_at').notNull(),
  },
  (t) => [
    uniqueIndex('comments_doc_author_key').on(t.documentId, t.authorId),
    index('comments_document_idx').on(t.documentId),
  ],
);

export const usageKindEnum = pgEnum('usage_kind', ['create', 'submit', 'update', 'comment']);

/**
 * Counters for the daily limits (D21). Kept apart from the entries so deleting an entry refunds nothing.
 * Incremented in the same transaction as the write it counts.
 */
export const dailyUsage = pgTable(
  'daily_usage',
  {
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    day: date('day', { mode: 'string' }).notNull(),
    kind: usageKindEnum('kind').notNull(),
    n: integer('n').notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.day, t.kind] })],
);

/**
 * Which leader opened which entry, and when (docs/ARCHITECTURE.md §5). A security log only: never shown to
 * diary owners (spec §5.4). Kept as long as activity events.
 */
export const readAudit = pgTable(
  'read_audit',
  {
    id: uuid('id').primaryKey(),
    /** Null once the leader's account is deleted; the username stays so the record still means something. */
    leaderId: uuid('leader_id').references(() => users.id, { onDelete: 'set null' }),
    leaderUsername: text('leader_username').notNull(),
    documentId: uuid('document_id')
      .notNull()
      .references(() => documents.id, { onDelete: 'cascade' }),
    readAt: timestamptz('read_at').notNull(),
  },
  (t) => [
    index('read_audit_document_idx').on(t.documentId, t.readAt),
    index('read_audit_read_at_idx').on(t.readAt),
  ],
);

// ---------------------------------------------------------------------------------------------------------
// 報數 (spec §7, docs/ARCHITECTURE.md §8.5). One app-wide total; no content, so nothing here is encrypted.

export const countEntries = pgTable(
  'count_entries',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    dailyCount: integer('daily_count').notNull(),
    /** The Beijing date the count is for: today or up to 5 days earlier (D23). */
    countDate: date('count_date', { mode: 'string' }).notNull(),
    submittedAt: timestamptz('submitted_at').notNull(),
    /** Made by the 02:00 job rather than the user. */
    auto: boolean('auto').notNull(),
    /**
     * Insertion order. A report replaces the user's earlier ones for the same count date, and two reports can
     * share a timestamp, so "latest" is decided by this, not by `submitted_at`.
     */
    seq: bigint('seq', { mode: 'number' }).generatedAlwaysAsIdentity().notNull(),
  },
  (t) => [
    check('count_entries_daily_count_range', sql`${t.dailyCount} BETWEEN 1 AND 1080`),
    index('count_entries_user_date_idx').on(t.userId, t.countDate, t.seq),
    index('count_entries_date_idx').on(t.countDate),
    // At most one auto entry per user per date, so running the job twice in a day changes nothing.
    uniqueIndex('count_entries_one_auto_key')
      .on(t.userId, t.countDate)
      .where(sql`${t.auto}`),
  ],
);

export const countSettings = pgTable(
  'count_settings',
  {
    userId: uuid('user_id')
      .primaryKey()
      .references(() => users.id, { onDelete: 'cascade' }),
    autoSubmit: boolean('auto_submit').notNull().default(false),
    /** The number the 02:00 job submits; 0 until the user has typed one. */
    savedCount: integer('saved_count').notNull().default(0),
    updatedAt: timestamptz('updated_at').notNull(),
  },
  (t) => [check('count_settings_saved_count_range', sql`${t.savedCount} BETWEEN 0 AND 1080`)],
);
